import { Link, NavLink } from 'react-router-dom'
// import Logo from '../../assets/images/png/logo.png'
import Logo from '../../assets/images/png/ms_pro.png'
import Dashboard from '../../assets/images/png/icons_dashboard.png'
import Appointments from '../../assets/images/png/calendar.png'
import WaitingAppointments from '../../assets/images/png/waiting_appointments.png'
import Prescriptions from '../../assets/images/png/bi_prescription.png'
import Report from '../../assets/images/png/document_report.png'
import Invoice from '../../assets/images/png/icons_invoice.png'
import Expenses from '../../assets/images/png/icons_expenses.png'
import UpdateProfile from '../../assets/images/png/icon_update_profile.png'
import Update from '../../assets/images/svg/updates.svg'
import Help from '../../assets/images/png/help.png'
import Setting from '../../assets/images/png/icon_settings.png'
